<?php
session_start(); require_once __DIR__ . '/config/database.php';
if ($_SERVER['REQUEST_METHOD']==='POST') {
  $id=(int)($_POST['product_id']??0); $action=$_POST['action']??'';
  if ($action==='add' && $id>0) { $check=$pdo->prepare("SELECT id FROM products WHERE id=?"); $check->execute([$id]); if($check->fetch()) $_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+1; }
  if ($action==='remove' && $id>0) unset($_SESSION['cart'][$id]);
  if ($action==='update' && isset($_POST['qty'][$id])) { $qty=max(1,min(20,(int)$_POST['qty'][$id])); $_SESSION['cart'][$id]=$qty; }
  header('Location: cart.php'); exit;
}
$cart=$_SESSION['cart']??[]; $items=[]; $total=0;
if($cart){$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$stmt=$pdo->prepare("SELECT * FROM products WHERE id IN ($marks)");$stmt->execute($ids);foreach($stmt->fetchAll() as $p){$p['qty']=$cart[$p['id']];$p['subtotal']=$p['price']*$p['qty'];$total+=$p['subtotal'];$items[]=$p;}}
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Your Cart | NovaCart</title><link rel="stylesheet" href="css/style.css"></head><body><header class="site-header"><a class="logo" href="index.php">Nova<span>Cart</span></a><button class="menu-toggle" aria-label="Toggle menu">☰</button><nav class="nav"><a href="index.php">Home</a><a href="products.php">Shop</a><a class="active" href="cart.php">Cart (<?= array_sum($cart) ?>)</a><a href="login.php">Login</a></nav></header><main class="page-wrap"><div class="page-title"><p class="eyebrow">YOUR BAG</p><h1>Shopping cart</h1><p>Review your picks before checkout.</p></div><?php if(!$items): ?><div class="empty-state"><span>🛍️</span><h2>Your cart is waiting</h2><p>Add a few favorites to get started.</p><a class="btn" href="products.php">Browse products</a></div><?php else: ?><div class="cart-layout"><div class="cart-items"><?php foreach($items as $p): ?><article class="cart-item"><div class="cart-emoji"><?= htmlspecialchars($p['emoji']) ?></div><div class="cart-details"><h3><?= htmlspecialchars($p['name']) ?></h3><p>₹<?= number_format($p['price'],2) ?> each</p><form method="post" class="qty-form"><input type="hidden" name="action" value="update"><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><label>Qty <input type="number" min="1" max="20" name="qty[<?= $p['id'] ?>]" value="<?= $p['qty'] ?>"></label><button class="small-btn" type="submit">Update</button></form></div><div class="cart-price"><strong>₹<?= number_format($p['subtotal'],2) ?></strong><form method="post"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><button class="remove-btn" type="submit">Remove</button></form></div></article><?php endforeach; ?></div><aside class="summary"><h2>Order summary</h2><div class="summary-line"><span>Subtotal</span><strong>₹<?= number_format($total,2) ?></strong></div><div class="summary-line"><span>Delivery</span><strong>Free</strong></div><hr><div class="summary-line total"><span>Total</span><strong>₹<?= number_format($total,2) ?></strong></div><a class="btn full-btn" href="checkout.php">Continue to checkout →</a><p class="muted">Demo checkout — no real payment is collected.</p></aside></div><?php endif; ?></main><footer class="footer"><a class="logo" href="index.php">Nova<span>Cart</span></a><small>© <?= date('Y') ?> NovaCart. Demo project.</small></footer><script src="js/script.js"></script></body></html>